import type { Href } from 'expo-router';

/**
 * Expo Router typed-route declarations are generated by Metro/Expo and can be
 * stale immediately after a patch adds new files. Keep runtime paths correct
 * while centralizing the narrow cast in one place instead of weakening router
 * typing throughout the screens.
 */
function href(value: string): Href {
  return value as unknown as Href;
}

export const PATIENTS_HREF = href('/patients');
export const NEW_PATIENT_HREF = href('/patients/new');
export const DELETED_PATIENTS_HREF = href('/patients/deleted');

export function patientHref(id: string): Href {
  return {
    pathname: '/patients/[id]',
    params: { id },
  } as unknown as Href;
}

export function patientEditHref(id: string): Href {
  return {
    pathname: '/patients/[id]/edit',
    params: { id },
  } as unknown as Href;
}
